def parse_size(val):
    # val like +10b, -10k, 10m etc
    m = re.match(r'^([+-]?)(\d+)([a-zA-Z]+)?$', val)
    if not m:
        return None
    sign = m.group(1)
    num = int(m.group(2))
    unit = (m.group(3) or 'b').lower()
    mult = {
        'b': 1,
        'k': 10**3,
        'm': 10**6,
        'g': 10**9,
        't': 10**12,
        'ki': 1024,
        'mi': 1024**2,
        'gi': 1024**3,
        'ti': 1024**4,
    }
    # Also allow kb etc? but we limited earlier
    if unit not in mult:
        # check kb etc alias
        if unit == 'kb':
            unit = 'k'
        elif unit == 'mb':
            unit = 'm'
        elif unit == 'gb':
            unit = 'g'
        elif unit == 'tb':
            unit = 't'
        elif unit == 'kib':
            unit = 'ki'
        elif unit == 'mib':
            unit = 'mi'
        elif unit == 'gib':
            unit = 'gi'
        elif unit == 'tib':
            unit = 'ti'
        else:
            return None
    size = num * mult[unit]
    # sign: '+' means >=, '-' means <=, no sign means ==
    if sign == '+':
        return ('gte', size)
    elif sign == '-':
        return ('lte', size)
    else:
        return ('eq', size)

