def parse_size(val):
    # val like +10b, -10k, 10m etc
    m = re.match(r'^([+-]?)(\d+)([a-zA-Z]+)?$', val)
    if not m:
        return None
    sign = m.group(1)
    num = int(m.group(2))
    unit = (m.group(3) or 'b').lower()
    mult = {
        'b': 1,
        'k': 10**3,
        'm': 10**6,
        'g': 10**9,
        't': 10**12,
        'ki': 1024,
        'mi': 1024**2,
        'gi': 1024**3,
        'ti': 1024**4,
    }
    # Also allow kb etc? but we limited earlier
    if unit not in mult:
        # check kb etc alias
        if unit == 'kb':
            unit = 'k'
        elif unit == 'mb':
            unit = 'm'
        elif unit == 'gb':
            unit = 'g'
        elif unit == 'tb':
            unit = 't'
        elif unit == 'kib':
            unit = 'ki'
        elif unit == 'mib':
            unit = 'mi'
        elif unit == 'gib':
            unit = 'gi'
        elif unit == 'tib':
            unit = 'ti'
        else:
            return None
    size = num * mult[unit]
    # sign: '+' means >=, '-' means <=, no sign means ==
    if sign == '+':
        return ('gte', size)
    elif sign == '-':
        return ('lte', size)
    else:
        return ('eq', size)

def parse_time(val):
    # returns timestamp (float) to compare file mtime against
    # val may be: YYYY-MM-DD HH:MM:SS, YYYY-MM-DD, @timestamp, duration like 1d, 10h, 35min, 2weeks, etc
    # For duration, we compare to now - duration
    # For alias, return timestamp
    val = val.strip()
    # Try @timestamp
    if val.startswith('@'):
        try:
            ts = float(val[1:])
            return ts
        except:
            return None
    # Try absolute date formats
    # Try parsing with strptime variants
    for fmt in ["%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%Y-%m-%d", "%Y/%m/%d %H:%M:%S", "%Y/%m/%d"]:
        try:
            t = time.strptime(val, fmt)
            return time.mktime(t)
        except:
            pass
    # Try duration: number + unit
    # Supported units: s, sec, secs, second, seconds, m, min, mins, minute, minutes, h, hour, hours, d, day, days, w, week, weeks, month? Let's support common
    m = re.match(r'^\s*(\d+)\s*([a-zA-Z]+)?\s*$', val)
    if m:
        num = int(m.group(1))
        unit = (m.group(2) or '').lower()
        mult = 0
        if unit in ['','s','sec','secs','second','seconds']:
            mult = 1
        elif unit in ['m','min','mins','minute','minutes']:
            mult = 60
        elif unit in ['h','hour','hours']:
            mult = 3600
        elif unit in ['d','day','days']:
            mult = 86400
        elif unit in ['w','week','weeks']:
            mult = 86400*7
        elif unit in ['month','months']:
            mult = 86400*30
        elif unit in ['y','year','years']:
            mult = 86400*365
        elif unit in ['ms','millisecond','milliseconds']:
            mult = 0.001
        elif unit == 'us' or unit == 'µs':
            mult = 1e-6
        else:
            # try like "2weeks" without space? Already captured "2weeks" as num=2 unit=weeks -> ok
            # if unit like "2weeks" includes digit? Our regex captures number plus letters, so "2weeks" -> num 2 unit weeks works
            # what about "1day"?
            # okay
            # if unknown unit, treat as invalid
            return None
        dur = num * mult
        return time.time() - dur
    # Also try combined like "1d", "10h", "35min" already covered? That is m above with no space but number+unit; regex handles 10h etc
    # Try with space? already
    # If still fails, return None
    return None

