    else:
        match_user = True
    if spec['group'] is not None:
        if g_target is None:
            match_group = False if not spec['group_neg'] else True
        else:
            is_eq = (gid == g_target)
            if spec['group_neg']:
                match_group = not is_eq
            else:
                match_group = is_eq
    else:
        match_group = True
    combined = match_user and match_group
    if spec['overall_neg']:
        combined = not combined
    return combined

